'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/textfield/md-gb-text-field.js';
import {TextFieldElement} from '@material/web/labs/gb/components/textfield/text-field-element.js';

/**
 * A Material Design text field (filled or outlined). Wraps <md-gb-text-field>.
 * Docs: https://material-web.dev/3.0/components/text-field/
 */
export const MdTextField = createComponent({
  react: React,
  tagName: 'md-gb-text-field',
  elementClass: TextFieldElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
    onInvalid: 'invalid' as EventName<Event>,
    onSelect: 'select' as EventName<Event>,
  },
});

export type MdTextFieldProps = React.ComponentProps<typeof MdTextField>;
